const {pathToFileURL}=require('node:url');
process.parentPort.once('message',async event=>{
 try{
  const {root,module,native,batch}=event.data;const load=p=>import(pathToFileURL(root+'/out/'+p).href);
  const [{RPCProtocol},{ProxyIdentifier},{VSBuffer},{Event}]=await Promise.all([load(module),load('vs/workbench/services/extensions/common/proxyIdentifier.js'),load('vs/base/common/buffer.js'),load('vs/base/common/event.js')]);
  const {RPCMessagePort}=await load('vs/workbench/services/extensions/common/rpcMessagePort.js');const port=event.ports[0];const post=message=>port.postMessage(message);const protocol=new RPCMessagePort(post);if(!batch)protocol.sendStructuredClone=post;port.on('message',e=>protocol.acceptMessage(e.data));port.start();
  const server=new RPCProtocol(protocol);const id=new ProxyIdentifier('electron-benchmark');server.set(id,{$echo:value=>value});
  process.parentPort.postMessage({ready:true,node:process.version,poolSize:Buffer.poolSize});
 }catch(error){process.parentPort.postMessage({error:String(error.stack)});}
});
